mapper.select:
SELECT chatroom_sq
FROM tbl_chatroom_s
WHERE project_sq = #{projectSq}
AND user_sq = #{userSq}

SELECT chatroom_user_is_deleted_yn
FROM tbl_chatroom_s
WHERE chatroom_sq = #{chatRoomSq}

mapper.update:
UPDATE tbl_chatroom_s
SET chatroom_user_is_deleted_yn = 'N'
WHERE chatroom_sq = #{chatRoomSq}

mapper.select:
SELECT company_sq
FROM tbl_project_m
WHERE project_sq = #{projectSq}

mapper.update:
UPDATE tbl_chatroom_s
SET last_message = #{lastMessage},
last_message_at = #{lastMessageAt}
WHERE chatroom_sq = #{chatRoomSq}

mapper.select:
SELECT company_sq
FROM tbl_company_s
WHERE user_sq = #{userSq}

mapper.update:
UPDATE tbl_chatroom_s
SET user_lastmessage_sq = #{lastReadMsgSq}
WHERE chatroom_sq = #{chatRoomSq}

UPDATE tbl_chatroom_s
SET company_lastmessage_sq = #{lastReadMsgSq}
WHERE chatroom_sq = #{chatRoomSq}
